        .panel-reader-v2,
        .panel-reader-v2 {
            font-family: var(--eng-reader-font);
            font-size: var(--eng-reader-font-size);
            line-height: var(--eng-reader-line-height);
            background-color: var(--eng-bg-main, #fdfdf8);
            color: var(--eng-reader-text, #3d3a2a);
            margin: 0;
            height: 100%;
            overflow: hidden;
            font-weight: 400;
            text-size-adjust: 100%;
            -webkit-text-size-adjust: 100%;
            -webkit-font-smoothing: auto;
        }

        .main-grid {
            display: grid;
            grid-template-columns: 33% 1fr;
            height: 100%;
            gap: var(--eng-reader-gap);
            align-items: start;
            box-sizing: border-box;
        }

        .text-col {
            padding: 0;
            overflow-y: auto;
            overflow-x: hidden;
            min-width: 0;
            height: 100%;
            box-sizing: border-box;
        }

        .dict-col {
            /* Local En→Vi result panel lives on the main page surface. */
            background: var(--eng-bg-main, #fdfdf8);
            border: 1px solid #d3d2ca;
            padding: var(--eng-reader-panel-padding);
            overflow-y: auto;
            border-radius: 0;
            box-sizing: border-box;
            height: 100%;
        }

        #english-reader-main-text table {
            width: 100%;
            border-collapse: collapse;
            table-layout: auto;
            border: 1px solid #d3d2ca;
            margin-top: 0;
        }

        #english-reader-main-text td {
            padding: var(--eng-reader-cell-padding);
            border: 1px solid #d3d2ca;
            vertical-align: middle;
        }

        #english-reader-main-text .id-col {
            font-family: var(--eng-reader-mono-font);
            font-size: var(--eng-reader-code-font-size);
            width: 1%;
            min-width: max-content;
            white-space: nowrap;
            text-align: center;
            padding: var(--eng-reader-id-cell-padding);
            color: inherit;
            box-sizing: border-box;
        }

        #english-reader-main-text .content-col {
            width: auto;
            min-width: 0;
            font-size: var(--eng-reader-font-size);
            line-height: var(--eng-reader-line-height);
            white-space: normal;
            word-break: normal;
            overflow-wrap: break-word;
        }

        #english-reader-main-text .eng-word {
            cursor: pointer;
            border-radius: 3px;
            transition: 0.15s;
            padding: var(--eng-reader-word-padding);
            display: inline;
            color: inherit;
        }

        #english-reader-main-text .eng-word:hover,
        #english-reader-main-text .eng-word.active,
        #english-reader-main-text .eng-word.active-en {
            background: var(--eng-bg-sec);
            border-bottom: 2px solid #5d7367;
            font-weight: 600;
            color: #5d7367;
        }

        /* English→Vietnamese overlay inside Longman/Oxford result HTML.
           Hover/active states intentionally do not change geometry. */
        .dict-col .eng-sub-word {
            cursor: pointer;
            color: inherit;
            background: transparent;
            border: none;
            padding: 0;
            margin: 0;
            border-radius: 0;
            font-weight: inherit;
            transition: color 0.15s, background-color 0.15s;
        }

        .dict-col .eng-sub-word:hover,
        .dict-col .eng-sub-word.active-en {
            color: #5d7367;
            background: rgba(93, 115, 103, 0.10);
            border: none;
            padding: 0;
            margin: 0;
            font-weight: inherit;
        }

